import requests
queries=['TITLE_ABS:(BANCR) AND TITLE_ABS:(bladder)','"BRAF-activated non-coding RNA" AND bladder','BANCR AND (urothelial OR bladder carcinoma)']
for q in queries:
 r=requests.get('https://www.ebi.ac.uk/europepmc/webservices/rest/search',params={'query':q,'format':'json','pageSize':20},timeout=20)
 print('\nQUERY',q,'status',r.status_code)
 for x in r.json().get('resultList',{}).get('result',[]): print(x.get('title'),x.get('authorString'),x.get('pubYear'),x.get('pmid'),x.get('doi'))
